@Override public void getPaymentMethods(GetPaymentMethodsRequest req, StreamObserver<GetPaymentMethodsReply> responseObserver) {
  try {
    var paymentMethods = coreApi.getFiatPaymentMethods().stream().map(PaymentMethod::toProtoMessage).collect(Collectors.toList());
    var reply = GetPaymentMethodsReply.newBuilder().addAllPaymentMethods(paymentMethods).build();
    responseObserver.onNext(reply);
    responseObserver.onCompleted();
  } catch (RuntimeException e) {
    responseObserver.onError(e);
  }
}
